          amdgpu::fp_mode::binary_f64(lhs_bits, rhs_bits, amdgpu::fp_mode::BinaryF64Op::Multiply,
                                      wf.fp_round_mode_f16_f64(), wf.fp_denorm_mode_f16_f64());
